{
     "title": "CSCI-519: Seminar in Computer Graphics - Orientation Companion",
     "learningObjectives": [
       "Define the core stages of the OpenGL graphics pipeline and their sequential processing of vertex data.",
       "Explain how geometric transformations, viewing models, and rasterization convert 3D scene representations into discrete pixel grids.",
       "Evaluate visual correctness by identifying how explicit conventions, sampling decisions, and measurable error bounds determine final image output."
     ],
     "beats": [
       {
         "title": "Pipeline Foundation: Vertex Processing",
         "claim": "The OpenGL graphics pipeline processes vertices through programmable shader stages.",
         "example": "Vertex attributes like position and normal are passed from the application to the vertex shader for initial transformation.",
         "visualDirection": "Display a flowchart showing vertices entering the vertex shader stage with labeled input/output attributes.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Primitive Assembly",
         "claim": "Primitive assembly groups vertices into points, lines, or triangles.",
         "example": "Three consecutive vertex indices are connected to form a triangle primitive that defines a planar surface.",
         "visualDirection": "Show a wireframe triangle with numbered vertex indices and a line connecting them to a primitive assembly buffer.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "View Volume Clipping",
         "claim": "Clipping removes portions outside the view volume.",
         "example": "A triangle extending beyond the camera's frustum is clipped at the clipping plane boundaries.",
         "visualDirection": "Illustrate a 3D cube with a frustum overlay, highlighting clipped edges and the resulting clipped polygon.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Rasterization Conversion",
         "claim": "Rasterization converts primitives into fragment candidates.",
         "example": "Each triangle is subdivided into a set of pixels, generating a fragment for every covered pixel.",
         "visualDirection": "Show a subdivided triangle with a rasterization mask indicating which pixels are covered.",
         "sourceIds": ["khronos-opengl", "mit-computer-graphics"]
       },
       {
         "title": "Interpolation Values",
         "claim": "Interpolation produces per-fragment values from vertex outputs.",
         "example": "Color and normal values are linearly interpolated across the triangle to determine per-fragment properties.",
         "visualDirection": "Display a triangle with gradient shading showing interpolated color values moving from vertex to fragment.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Fragment Processing",
         "claim": "Fragment processing computes values for framebuffer operations.",
         "example": "The fragment shader calculates final color, alpha, and depth values for each pixel.",
         "visualDirection": "Show a fragment shader code snippet with labeled inputs and outputs mapping to framebuffer writes.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Depth Testing Visibility",
         "claim": "Depth testing resolves visibility according to stored depth values.",
         "example": "A fragment is discarded if its computed depth exceeds the stored depth value in the depth buffer.",
         "visualDirection": "Illustrate a depth buffer comparison with a foreground fragment passing and a background fragment failing.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Blending Operations",
         "claim": "Blending combines a fragment result with an existing framebuffer value.",
         "example": "Alpha blending mixes the new fragment color with the existing pixel color using a specified blend factor.",
         "visualDirection": "Show a split screen with a semi-transparent overlay blending onto a base image using a blend equation.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Coordinate Spaces and Sampling",
         "claim": "Coordinate spaces, sampling, and numerical precision must remain explicit.",
         "example": "Texture coordinates are explicitly mapped from object space to UV space to avoid sampling artifacts.",
         "visualDirection": "Display a texture coordinate grid on a 3D surface with explicit UV mapping lines and sampling points.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "Visual correctness follows from explicit conventions, assumptions, sampling decisions, and measurable error.",
         "example": "A checklist verifies explicit coordinate mappings, proper sampling rates, and error bounds before rendering.",
         "visualDirection": "Show a checklist graphic with checkboxes for explicit conventions, sampling decisions, measurable error, and assumptions.",
         "sourceIds": ["mit-computer-graphics"]
       }
     ]
   }
